import boto3
import os
from typing import Union, BinaryIO

def upload_to_object_storage(
    bucket_name: str,
    object_name: str,
    data: Union[str, bytes, BinaryIO],
    content_type: str = "application/octet-stream"
) -> str:
    s3_client = boto3.client(
        "s3",
        aws_access_key_id=os.getenv("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=os.getenv("AWS_SECRET_ACCESS_KEY"),
        region_name=os.getenv("AWS_DEFAULT_REGION", "us-east-1")
    )
    extra_args = {"ContentType": content_type} if content_type else {}
    if isinstance(data, str):
        # local file path
        with open(data, "rb") as f:
            s3_client.upload_fileobj(
                Fileobj=f, Bucket=bucket_name, Key=object_name, ExtraArgs=extra_args
            )
    elif isinstance(data, bytes):
        s3_client.put_object(
            Bucket=bucket_name, Key=object_name, Body=data, **extra_args
        )
    elif hasattr(data, "read"):
        # byte stream
        s3_client.upload_fileobj(
            Fileobj=data, Bucket=bucket_name, Key=object_name, ExtraArgs=extra_args
        )
    else:
        raise TypeError("data must be str (file path), bytes, or file-like object")
    return f"https://{bucket_name}.s3.amazonaws.com/{object_name}"
